# --------------------------------------------------------------------------- #
# 音檔長度 / 格式探測（純標準庫）
# --------------------------------------------------------------------------- #
_MP3_BR = [
    [0, 32, 64, 96, 128, 160, 192, 224, 256, 288, 320, 352, 384, 416, 448],
    [0, 32, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 384],
    [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320],
    [0, 32, 48, 56, 64, 80, 96, 112, 128, 144, 160, 176, 192, 224, 256],
    [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160],
]
_MP3_SR = {3: [44100, 48000, 32000], 2: [22050, 24000, 16000], 0: [11025, 12000, 8000]}
_MODE = {0: 'stereo', 1: 'joint', 2: 'dual', 3: 'mono'}


def _probe_mp3(data: bytes) -> dict:
    i = 0
    if data[:3] == b'ID3':
        i = 10 + ((data[6] & 0x7F) << 21 | (data[7] & 0x7F) << 14
                  | (data[8] & 0x7F) << 7 | (data[9] & 0x7F))
    total = 0.0
    frames = 0
    brs, srs, modes = set(), set(), set()
    n = len(data)
    while i < n - 4:
        if data[i] == 0xFF and (data[i + 1] & 0xE0) == 0xE0:
            h = struct.unpack('>I', data[i:i + 4])[0]
            ver, layer = (h >> 19) & 3, (h >> 17) & 3
            bri, sri = (h >> 12) & 0xF, (h >> 10) & 3
            pad, mode = (h >> 9) & 1, (h >> 6) & 3
            if layer == 0 or ver == 1 or sri == 3 or bri in (0, 15):
                i += 1
                continue
            srate = _MP3_SR[ver][sri]
            row = (3 - layer) if ver == 3 else (3 if layer == 3 else 4)
            bitrate = _MP3_BR[row][bri]
            spf = 384 if layer == 3 else (1152 if layer == 2 else (1152 if ver == 3 else 576))
            flen = int(spf / 8 * bitrate * 1000 / srate) + pad
            if flen <= 0:
                i += 1
                continue
            total += spf / srate
            frames += 1
            brs.add(bitrate)
            srs.add(srate)
            modes.add(mode)
            i += flen
        else:
            i += 1
    bitrate = None
    if brs:
        bitrate = min(brs) if len(brs) == 1 else 'VBR%d-%d' % (min(brs), max(brs))
    return {
        'dur': round(total, 2),
        'frames': frames,
        'bitrate': bitrate,
        'samplerate': sorted(srs)[0] if srs else None,
        'channels': _MODE.get(min(modes), '?') if modes else '?',
    }


def _probe_mp4(data: bytes) -> dict:
    """在 moov/mvhd 裡找 timescale / duration。"""
    idx = data.find(b'mvhd')
    if idx < 0:
        return {'dur': 0.0, 'note': 'mvhd 找不到'}
    p = idx + 4
    ver = data[p]
    if ver == 1:
        ts = struct.unpack('>I', data[p + 20:p + 24])[0]
        du = struct.unpack('>Q', data[p + 24:p + 32])[0]
    else:
        ts = struct.unpack('>I', data[p + 12:p + 16])[0]
        du = struct.unpack('>I', data[p + 16:p + 20])[0]
    return {'dur': round(du / ts, 2) if ts else 0.0, 'bitrate': None,
            'samplerate': None, 'channels': '?'}


def _probe_wav(data: bytes) -> dict:
    if data[:4] != b'RIFF':
        return {'dur': 0.0}
    sr = struct.unpack('<I', data[24:28])[0]
    byte_rate = struct.unpack('<I', data[28:32])[0]
    ch = struct.unpack('<H', data[22:24])[0]
    idx = data.find(b'data', 12)
    size = struct.unpack('<I', data[idx + 4:idx + 8])[0] if idx > 0 else 0
    return {'dur': round(size / byte_rate, 2) if byte_rate else 0.0,
            'bitrate': byte_rate * 8 // 1000, 'samplerate': sr,
            'channels': 'mono' if ch == 1 else '%dch' % ch}


def probe_audio(path) -> dict:
    path = Path(path)
    data = path.read_bytes()
    ext = path.suffix.lower()
    try:
        if ext == '.mp3':
            info = _probe_mp3(data)
        elif ext in ('.m4a', '.mp4', '.aac'):
            info = _probe_mp4(data)
        elif ext == '.wav':
            info = _probe_wav(data)
        else:
            info = {'dur': 0.0, 'note': '%s 不支援長度解析' % ext}
    except Exception as exc:  # 壞檔不要讓整批停下來
        info = {'dur': 0.0, 'note': '解析失敗: %s' % exc}
    info.update(file=path.name, stem=path.stem, size=path.stat().st_size,
                ext=ext, path=str(path))
    return info


def scan_audio_dir(folder) -> list:
    folder = Path(folder)
    if not folder.is_dir():
        raise SystemExit('[audio_lib] 音檔資料夾不存在：%s' % folder)
    files = [p for p in sorted(folder.rglob('*')) if p.suffix.lower() in AUDIO_EXT]
    return [probe_audio(p) for p in files]


# --------------------------------------------------------------------------- #
# clip key
# --------------------------------------------------------------------------- #
_SECTION_RE = re.compile(r'^(MG|FG|SG|JP|CM)_(BGM|SFX|MIX|VO)_(.+)$', re.I)
_PREFIX_RE = re.compile(r'^([A-Za-z0-9]+)_((?:MG|FG|SG|JP|CM)_(?:BGM|SFX|MIX|VO)_.+)$', re.I)


def strip_game_prefix(stem: str, prefix=None) -> str:
    """去掉遊戲代號前綴：'1024_MG_SFX_SpinStart' -> 'MG_SFX_SpinStart'。"""
    if prefix and stem.lower().startswith(prefix.lower() + '_'):
        return stem[len(prefix) + 1:]
    m = _PREFIX_RE.match(stem)
    return m.group(2) if m else stem


def detect_game_prefix(stems):
    """交付檔名的共同前綴（'1024_MG_SFX_x' -> '1024'）；抓不到回 None。"""
    heads = {}
    for s in stems:
        m = _PREFIX_RE.match(s)
        if m:
            heads[m.group(1)] = heads.get(m.group(1), 0) + 1
    if not heads:
        return None
    top, cnt = max(heads.items(), key=lambda kv: kv[1])
    return top if cnt >= 2 else None


def short_key(key: str) -> str:
    """'MG_SFX_SpinStart' -> 'SpinStart'。

    只縮 SFX；BGM / MIX 原樣保留（那些名字本身就靠 MG_/FG_ 區分，縮了會看不懂）。
    """
    m = _SECTION_RE.match(key)
    if not m or m.group(2).upper() != 'SFX':
        return key
    return m.group(3)


def make_keys(stems, prefix=None, short=False) -> dict:
    """回傳 {stem: clip_key}；短名撞名時該筆自動退回長名。"""
    base = {s: strip_game_prefix(s, prefix) for s in stems}
    if not short:
        return base
    buckets = {}
    for stem, long_key in base.items():
        buckets.setdefault(short_key(long_key), []).append(stem)
    out = {}
    for stem, long_key in base.items():
        sk = short_key(long_key)
        out[stem] = long_key if len(buckets[sk]) > 1 else sk
    return out


