# --------------------------------------------------------------------------- #
# 音檔長度 / 格式探測（純標準庫）
# --------------------------------------------------------------------------- #
_MP3_BR = [
    [0, 32, 64, 96, 128, 160, 192, 224, 256, 288, 320, 352, 384, 416, 448],
    [0, 32, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 384],
    [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320],
    [0, 32, 48, 56, 64, 80, 96, 112, 128, 144, 160, 176, 192, 224, 256],
    [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160],
]
_MP3_SR = {3: [44100, 48000, 32000], 2: [22050, 24000, 16000], 0: [11025, 12000, 8000]}
_MODE = {0: 'stereo', 1: 'joint', 2: 'dual', 3: 'mono'}


def _probe_mp3(data: bytes) -> dict:
    i = 0
    if data[:3] == b'ID3':
        i = 10 + ((data[6] & 0x7F) << 21 | (data[7] & 0x7F) << 14
                  | (data[8] & 0x7F) << 7 | (data[9] & 0x7F))
    total = 0.0
    frames = 0
    brs, srs, modes = set(), set(), set()
    n = len(data)
    while i < n - 4:
        if data[i] == 0xFF and (data[i + 1] & 0xE0) == 0xE0:
            h = struct.unpack('>I', data[i:i + 4])[0]
            ver, layer = (h >> 19) & 3, (h >> 17) & 3
            bri, sri = (h >> 12) & 0xF, (h >> 10) & 3
            pad, mode = (h >> 9) & 1, (h >> 6) & 3
            if layer == 0 or ver == 1 or sri == 3 or bri in (0, 15):
                i += 1
                continue
            srate = _MP3_SR[ver][sri]
            row = (3 - layer) if ver == 3 else (3 if layer == 3 else 4)
            bitrate = _MP3_BR[row][bri]
            spf = 384 if layer == 3 else (1152 if layer == 2 else (1152 if ver == 3 else 576))
            flen = int(spf / 8 * bitrate * 1000 / srate) + pad
            if flen <= 0:
                i += 1
                continue
            total += spf / srate
            frames += 1
            brs.add(bitrate)
            srs.add(srate)
            modes.add(mode)
            i += flen
        else:
            i += 1
    bitrate = None
    if brs:
        bitrate = min(brs) if len(brs) == 1 else 'VBR%d-%d' % (min(brs), max(brs))
    return {
        'dur': round(total, 2),
        'frames': frames,
        'bitrate': bitrate,
        'samplerate': sorted(srs)[0] if srs else None,
        'channels': _MODE.get(min(modes), '?') if modes else '?',
    }


def _probe_mp4(data: bytes) -> dict:
    """在 moov/mvhd 裡找 timescale / duration。"""
    idx = data.find(b'mvhd')
    if idx < 0:
        return {'dur': 0.0, 'note': 'mvhd 找不到'}
    p = idx + 4
    ver = data[p]
    if ver == 1:
        ts = struct.unpack('>I', data[p + 20:p + 24])[0]
        du = struct.unpack('>Q', data[p + 24:p + 32])[0]
    else:
        ts = struct.unpack('>I', data[p + 12:p + 16])[0]
        du = struct.unpack('>I', data[p + 16:p + 20])[0]
    return {'dur': round(du / ts, 2) if ts else 0.0, 'bitrate': None,
            'samplerate': None, 'channels': '?'}


def _probe_wav(data: bytes) -> dict:
    if data[:4] != b'RIFF':
        return {'dur': 0.0}
    sr = struct.unpack('<I', data[24:28])[0]
    byte_rate = struct.unpack('<I', data[28:32])[0]
    ch = struct.unpack('<H', data[22:24])[0]
    idx = data.find(b'data', 12)
    size = struct.unpack('<I', data[idx + 4:idx + 8])[0] if idx > 0 else 0
    return {'dur': round(size / byte_rate, 2) if byte_rate else 0.0,
            'bitrate': byte_rate * 8 // 1000, 'samplerate': sr,
            'channels': 'mono' if ch == 1 else '%dch' % ch}


def probe_audio(path) -> dict:
    path = Path(path)
    data = path.read_bytes()
    ext = path.suffix.lower()
    try:
        if ext == '.mp3':
            info = _probe_mp3(data)
        elif ext in ('.m4a', '.mp4', '.aac'):
            info = _probe_mp4(data)
        elif ext == '.wav':
            info = _probe_wav(data)
        else:
            info = {'dur': 0.0, 'note': '%s 不支援長度解析' % ext}
    except Exception as exc:  # 壞檔不要讓整批停下來
        info = {'dur': 0.0, 'note': '解析失敗: %s' % exc}
    info.update(file=path.name, stem=path.stem, size=path.stat().st_size,
                ext=ext, path=str(path))
    return info


def scan_audio_dir(folder) -> list:
    folder = Path(folder)
    if not folder.is_dir():
        raise SystemExit('[audio_lib] 音檔資料夾不存在：%s' % folder)
    files = [p for p in sorted(folder.rglob('*')) if p.suffix.lower() in AUDIO_EXT]
    return [probe_audio(p) for p in files]


# --------------------------------------------------------------------------- #
# clip key
# --------------------------------------------------------------------------- #
_SECTION_RE = re.compile(r'^(MG|FG|SG|JP|CM)_(BGM|SFX|MIX|VO)_(.+)$', re.I)
_PREFIX_RE = re.compile(r'^([A-Za-z0-9]+)_((?:MG|FG|SG|JP|CM)_(?:BGM|SFX|MIX|VO)_.+)$', re.I)


def strip_game_prefix(stem: str, prefix=None) -> str:
    """去掉遊戲代號前綴：'1024_MG_SFX_SpinStart' -> 'MG_SFX_SpinStart'。"""
    if prefix and stem.lower().startswith(prefix.lower() + '_'):
        return stem[len(prefix) + 1:]
    m = _PREFIX_RE.match(stem)
    return m.group(2) if m else stem


def detect_game_prefix(stems):
    """交付檔名的共同前綴（'1024_MG_SFX_x' -> '1024'）；抓不到回 None。"""
    heads = {}
    for s in stems:
        m = _PREFIX_RE.match(s)
        if m:
            heads[m.group(1)] = heads.get(m.group(1), 0) + 1
    if not heads:
        return None
    top, cnt = max(heads.items(), key=lambda kv: kv[1])
    return top if cnt >= 2 else None


def short_key(key: str) -> str:
    """'MG_SFX_SpinStart' -> 'SpinStart'。

    只縮 SFX；BGM / MIX 原樣保留（那些名字本身就靠 MG_/FG_ 區分，縮了會看不懂）。
    """
    m = _SECTION_RE.match(key)
    if not m or m.group(2).upper() != 'SFX':
        return key
    return m.group(3)


def make_keys(stems, prefix=None, short=False) -> dict:
    """回傳 {stem: clip_key}；短名撞名時該筆自動退回長名。"""
    base = {s: strip_game_prefix(s, prefix) for s in stems}
    if not short:
        return base
    buckets = {}
    for stem, long_key in base.items():
        buckets.setdefault(short_key(long_key), []).append(stem)
    out = {}
    for stem, long_key in base.items():
        sk = short_key(long_key)
        out[stem] = long_key if len(buckets[sk]) > 1 else sk
    return out


# --------------------------------------------------------------------------- #
# 規格表（xlsx / csv）
# --------------------------------------------------------------------------- #
#: 規格表欄位 -> 內部欄名。比對時去掉空白、取「包含」關係。
COLUMN_ALIASES = {
    'no': ['編號', '序號', 'no', 'id'],
    'scene': ['運用場景', '使用場景', '場景', '用途'],
    'kind': ['類型', '種類'],
    'filename': ['檔名', '檔案名稱', 'filename', 'file'],
    'melody': ['旋律'],
    'loop': ['loop', '循環'],
    'power': ['強度'],
    'length': ['聲音長度', '長度', '秒數'],
    'desc': ['需求說明', '說明', '腳本'],
    'ref_video': ['示意影片檔名', '示意影片'],
    'ref_time': ['示意影片時間點', '時間點'],
    'ref_sound': ['參考影片或聲音檔', '參考聲音', '參考'],
    'note': ['備註'],
    'modify': ['修改說明'],
    'accept': ['驗收'],
}


def _norm(s) -> str:
    return re.sub(r'\s+', '', str(s or '')).lower()


def _map_columns(header_rows) -> dict:
    """規格表的表頭常跨 2~3 列，把前幾列疊起來一起比對。"""
    width = max(len(r) for r in header_rows)
    merged = []
    for c in range(width):
        merged.append(''.join(_norm(r[c]) if c < len(r) else '' for r in header_rows))
    mapping = {}
    for field, names in COLUMN_ALIASES.items():
        for c, text in enumerate(merged):
            if text and any(_norm(n) in text for n in names):
                mapping.setdefault(field, c)
                break
    return mapping


def _read_rows(path: Path, sheet=None):
    if path.suffix.lower() in ('.xlsx', '.xlsm'):
        try:
            import openpyxl
        except ImportError:
            raise SystemExit('[audio_lib] 讀 .xlsx 需要 openpyxl：pip install openpyxl')
        wb = openpyxl.load_workbook(path, data_only=True)
        ws = wb[sheet] if sheet else wb.worksheets[0]
        return [['' if v is None else str(v).strip() for v in r]
                for r in ws.iter_rows(values_only=True)]
    if path.suffix.lower() in ('.csv', '.tsv'):
        import csv
        delim = '\t' if path.suffix.lower() == '.tsv' else ','
        with path.open(encoding='utf-8-sig', newline='') as fh:
            return [[c.strip() for c in r] for r in csv.reader(fh, delimiter=delim)]
    raise SystemExit('[audio_lib] 規格表只支援 .xlsx/.csv/.tsv：%s' % path.name)


def read_spec(path, sheet=None) -> list:
    """讀規格表，回傳 list of dict。

    容許：表頭跨列、章節標題列（MAIN GAME / FREE GAME）、空白列、
    「檔名」欄寫成 `X_1~3` 這種一列代表多支的寫法（保留原字串，由對帳處理）。
    """
    path = Path(path)
    rows = _read_rows(path, sheet)
    head = next((i for i, r in enumerate(rows)
                 if any('檔名' in _norm(c) or _norm(c) in ('filename', 'file')
                        for c in r)), None)
    if head is None:
        raise SystemExit('[audio_lib] 規格表找不到「檔名」欄，無法解析')
    mapping = _map_columns(rows[head:head + 3])
    if 'filename' not in mapping:
        raise SystemExit('[audio_lib] 規格表找不到「檔名」欄，無法解析')

    def cell(row, field):
        c = mapping.get(field)
        return row[c].strip() if c is not None and c < len(row) else ''

    out, section = [], ''
    for row in rows[head + 1:]:
        if not any(row):
            continue
        first = row[0].strip() if row else ''
        if not cell(row, 'filename'):
            # 只有一兩欄有字 -> 視為章節標題列（MAIN GAME / FREE GAME）
            if first and len([c for c in row if c.strip()]) <= 2:
                section = first
            continue
        out.append({
            'section': section,
            'no': cell(row, 'no'),
            'scene': cell(row, 'scene'),
            'kind': cell(row, 'kind'),
            'filename': cell(row, 'filename'),
            'melody': cell(row, 'melody'),
            'loop': cell(row, 'loop'),
            'power': cell(row, 'power'),
            'length': cell(row, 'length'),
            'desc': cell(row, 'desc'),
            'ref_video': cell(row, 'ref_video'),
            'ref_time': cell(row, 'ref_time'),
            'ref_sound': cell(row, 'ref_sound'),
            'note': cell(row, 'note'),
        })
    return out


def spec_seconds(text):
    """'30~40' -> 40.0；'5+8+10' -> 23.0；'1.5s' -> 1.5；讀不出來 None。"""
    t = str(text or '').replace('s', '').replace('秒', '').strip()
    if not t:
        return None
    nums = re.findall(r'[\d.]+', t)
    if not nums:
        return None
    if '+' in t:
        return round(sum(float(n) for n in nums), 2)
    return float(nums[-1])


def expand_spec_filename(name: str):
    """'X_1~3' -> ['X_1','X_2','X_3']；其餘回 [name]。"""
    m = re.match(r'^(.*?)(\d+)\s*~\s*(\d+)$', name.strip())
    if not m:
        return [name.strip()]
    head, a, b = m.group(1), int(m.group(2)), int(m.group(3))
    if b < a or b - a > 20:
        return [name.strip()]
    return ['%s%d' % (head, i) for i in range(a, b + 1)]


def is_loop(spec_row) -> bool:
    return str(spec_row.get('loop', '')).strip().upper() in ('O', 'YES', 'TRUE', '1', 'V')


def is_music(spec_row) -> bool:
    """類型含「音樂」且不含「音效」，或檔名有 _BGM_ -> 走 BGM group / playMusic。"""
    kind = str(spec_row.get('kind', ''))
    if '_BGM_' in str(spec_row.get('filename', '')).upper():
        return True
    return ('音樂' in kind or 'music' in kind.lower()) and '音效' not in kind


def suggest_volume(spec_row) -> float:
    """volume 一律 1。

    規格的「強度」欄是音色設計的相對強弱（音效師混音時就做進音檔了），
    不是播放音量，拿它推 volume 只會讓每支音都偏掉一點、又沒有依據。
    真正的音量平衡請在遊戲內 AudioMixer 面板調，調完用
    `SoundManager.exportAudioMixerJsonFile()` 匯出回寫。
    """
    return 1.0


# --------------------------------------------------------------------------- #
# 專案內位置
# --------------------------------------------------------------------------- #
def bundle_dir(root: Path, name=DEFAULT_BUNDLE) -> Path:
    """已存在就用既有位置，否則有 assets/Bundle 放它底下，沒有就放 assets 底下。"""
    root = Path(root)
    for cand in (root / 'assets' / name, root / 'assets' / 'Bundle' / name):
        if cand.is_dir():
            return cand
    base = root / 'assets' / 'Bundle'
    if not base.is_dir():
        base = root / 'assets'
    return base / name


def game_code(root: Path):
    """從 assets/Game/Script/G####_*.ts 或場景名推遊戲代號（G1028）。"""
    root = Path(root)
    for p in sorted((root / 'assets' / 'Game').rglob('G[0-9][0-9][0-9][0-9]_*.ts')):
        m = re.match(r'^(G\d{4})_', p.name)
        if m:
            return m.group(1)
    for p in sorted((root / 'assets' / 'Game').rglob('*.scene')):
        m = re.search(r'(G\d{4})', p.name)
        if m:
            return m.group(1)
    return None


def game_name(root: Path):
    """Scene_G1028_WildFrontier.scene -> WildFrontier。"""
    for p in sorted((Path(root) / 'assets' / 'Game').rglob('*.scene')):
        m = re.match(r'^Scene_G\d{4}_(.+)\.scene$', p.name)
        if m:
            return m.group(1)
    return None


def main_scene(root: Path):
    scenes = sorted((Path(root) / 'assets' / 'Game').rglob('Scene_*.scene'))
    return scenes[0] if scenes else None


def sound_dir(root: Path) -> Path:
    """AudioMixer json 與隨場景載入的 BGM 放這裡（與 BrawlRooster 一致）。"""
    return Path(root) / 'assets' / 'Game' / 'game' / 'Sound'


def manifest_path(root: Path) -> Path:
    return Path(root) / 'audio_data' / 'audio_manifest.json'


def load_manifest(root: Path) -> dict:
    p = manifest_path(root)
    if not p.is_file():
        raise SystemExit('[audio_lib] 找不到 %s，請先跑 audio_manifest.py' % p)
    return load_json(p)


def overrides_path(root: Path) -> Path:
    return Path(root) / 'audio_data' / 'audio_overrides.json'


def load_overrides(root: Path) -> dict:
    """人工覆寫規格推導出來的 mixer 值。

    規格表偶爾會填錯（例如 Intro 的 LOOP 欄標 O，但它必須播一次就接 Loop）。
    這種偏差寫在 audio_data/audio_overrides.json，讓產生器與驗收都認同一份，
    而不是去手改產生出來的 json —— 手改的下次重跑就沒了、也查不到理由。

        {
          "clips": {
            "MG_BGM_Intro": {"loop": 0, "_why": "Intro 播一次就接 Loop，規格 LOOP 欄填錯"}
          }
        }
    """
    p = overrides_path(root)
    if not p.is_file():
        return {}
    data = load_json(p)
    return data.get('clips', data if 'aliases' not in data else {}) or {}


def load_groups(root: Path) -> dict:
    """mixer 的 Group 定義，順便指定哪些 clip 屬於該 group。

        "groups": {
          "WIN": {"volume": 1, "limit": 0, "limitType": "first",
                  "clips": ["MG_MIX_BigWinLoop"]}
        }

    `clips` 只是給產生器用的歸屬清單，不會寫進 json 的 Group 區。
    """
    p = overrides_path(root)
    if not p.is_file():
        return {}
    return load_json(p).get('groups', {}) or {}


def load_ducks(root: Path) -> dict:
    """Duck 設定：某個 group 在播的時候，把另一個 group 壓低。

        "duck": {"WIN": {"BGM": {"volCut": -90, "begUnduck": 100, "unduckTime": 1}}}

    volCut 單位是 dB（-90 約等於靜音）；begUnduck 是「觸發音播放進度的百分比」，
    到了才開始用 unduckTime 秒淡回。語意見 AudioMixerStructure.DuckedGroup。
    """
    p = overrides_path(root)
    if not p.is_file():
        return {}
    return load_json(p).get('duck', {}) or {}


def load_aliases(root: Path) -> dict:
    """把底層寫死的 clip key 指到這台遊戲的某支音檔。

    底層會主動呼叫 wheel_stop / CM_Spin / trigger_alarm1 這些 key（見 RESERVED_KEYS）。
    清單裡沒有同名 clip 就完全沒聲音。用 alias 把它們指到自己的音檔，
    比繞過底層自己播安全，而且不用改 submodule。

        {
          "aliases": {
            "wheel_stop": {"target": "MG_SFX_ReelStop_1", "_why": "底層停輪音 fallback"},
            "CM_Spin":    {"target": "MG_SFX_SpinStart"}
          }
        }

    也可以簡寫成 {"wheel_stop": "MG_SFX_ReelStop_1"}。
    """
    p = overrides_path(root)
    if not p.is_file():
        return {}
    raw = load_json(p).get('aliases', {}) or {}
    out = {}
    for key, val in raw.items():
        out[key] = {'target': val} if isinstance(val, str) else dict(val)
    return out

# -*- coding: utf-8 -*-
"""驗收：把「音檔 / AudioMixer json / AudioClipList.prefab / 程式引用 / 場景接線」
五邊對齊起來檢查。任何一邊漏掉，症狀都是「沒聲音但也沒錯誤」。

檢查項目：
  1. bundle 目錄的 isBundle（沒設 -> 整包載不到）
  2. prefab 清單裡的 audioClip uuid 是否真的指到存在的音檔
  3. prefab 清單 vs AudioMixer json：json 沒有的 clip 會用預設值（volume 1、不 loop）
  4. loop clip 是否真的設了 loop: -1（漏掉 -> BGM 只播一次就沒了）
  5. 場景的 AudioMixerFileLoader.audioMixerFile 有沒有接（null -> 整份混音設定沒生效）
  6. 程式裡 play()/playMusic() 的字串字面值是否都在清單內（打錯字只會印 warn）
  7. clip key 是否撞到底層保留 key

退出碼：0 全過、1 有錯。
用法： python check_audio.py
"""
from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import audio_lib as L  # noqa: E402

MIXER_LOADER_TS = 'assets/CommonModule/Script/Manager/AudioTool/AudioMixerFileLoader.ts'
CONTAINER_TS = 'assets/CommonModule/Script/Audio/AudioClipContainer.ts'
PLAY_RE = re.compile(r"audioManager\s*\.\s*(play|playMusic|playOn|stop)\s*\(\s*'([^']+)'")
PLAY_RE2 = re.compile(r"SoundManager\.instance\s*\.\s*(play|playMusic|playOn)\s*\(\s*'([^']+)'")


def prefab_clips(prefab: Path):
    """回傳 [(clipName, uuid)]，把所有 AudioClipContainer 的清單合起來。"""
    if not prefab.is_file():
        return None
    data = L.load_json(prefab)
    out = []
    for o in data:
        if isinstance(o, dict) and o.get('__type__') == 'CommonAudioSetting':
            out.append((o.get('clipName', ''), (o.get('audioClip') or {}).get('__uuid__')))
    return out


def split_severity(items, own_keys):
    """屬於這台遊戲的 clip 沒接好是錯；共用清單那些名字在參考專案本來就多半是空的。"""
    mine = [n for n in items if n in own_keys]
    others = [n for n in items if n not in own_keys]
    return mine, others


def asset_uuid_index(root: Path):
    """{uuid: 相對路徑}，只掃音檔的 .meta。"""
    idx = {}
    for meta in (root / 'assets').rglob('*.meta'):
        if meta.suffix != '.meta':
            continue
        asset = Path(str(meta)[:-5])
        if asset.suffix.lower() not in L.AUDIO_EXT:
            continue
        u = L.read_meta_uuid(asset)
        if u:
            idx[u] = str(asset.relative_to(root)).replace('\\', '/')
    return idx


def scene_mixer_wired(root: Path):
    """回傳 (是否接上, 說明)。"""
    scene = L.main_scene(root)
    if not scene:
        return None, '找不到 assets/Game/**/Scene_*.scene'
    try:
        type_id = L.script_type_id(root, MIXER_LOADER_TS)
    except SystemExit:
        return None, '找不到 AudioMixerFileLoader.ts.meta'
    data = json.loads(scene.read_text(encoding='utf-8'))
    comps = [o for o in data if isinstance(o, dict) and o.get('__type__') == type_id]
    if not comps:
        return False, '%s 裡沒有 AudioMixerFileLoader 元件' % scene.name
    wired = [c for c in comps if (c.get('audioMixerFile') or {}).get('__uuid__')]
    if not wired:
        return False, '%s 的 AudioMixerFileLoader.audioMixerFile = null' % scene.name
    return True, '%s 已接 uuid=%s' % (scene.name, wired[0]['audioMixerFile']['__uuid__'][:8])


def code_refs(root: Path):
    """遊戲層程式裡出現的 clip 字串字面值 -> [檔案:行]。"""
    refs = {}
    game = root / 'assets' / 'Game'
    if not game.is_dir():
        return refs
    for ts in game.rglob('*.ts'):
        try:
            text = ts.read_text(encoding='utf-8')
        except Exception:
            continue
        for i, line in enumerate(text.splitlines(), 1):
            if line.lstrip().startswith('//'):
                continue
            for rx in (PLAY_RE, PLAY_RE2):
                for m in rx.finditer(line):
                    refs.setdefault(m.group(2), []).append(
                        '%s:%d' % (ts.relative_to(root).as_posix(), i))
    return refs


def main():
    L.utf8_stdout()
    ap = argparse.ArgumentParser()
    ap.add_argument('--root', default=None)
    ap.add_argument('--bundle', default=L.DEFAULT_BUNDLE)
    args = ap.parse_args()

    root = Path(args.root) if args.root else L.find_project_root(Path.cwd())
    errs, warns, oks = [], [], []
    aliases = L.load_aliases(root)
    try:
        own_keys = {c['key'] for c in L.load_manifest(root)['clips']} | set(aliases)
    except SystemExit:
        own_keys = set(aliases)

    # 1 bundle
    bdir = L.bundle_dir(root, args.bundle)
    bmeta = Path(str(bdir) + '.meta')
    if not bdir.is_dir():
        errs.append('找不到 bundle 目錄 %s' % bdir.relative_to(root))
    elif not bmeta.is_file() or not L.load_json(bmeta).get('userData', {}).get('isBundle'):
        errs.append('%s.meta 的 userData.isBundle 沒設 -> 整包載不到' % bdir.name)
    else:
        oks.append('bundle %s isBundle = true' % bdir.relative_to(root))

    # 2/3 prefab vs 音檔 vs mixer json
    prefab = bdir / 'Prefab' / 'AudioClipList.prefab'
    pc = prefab_clips(prefab)
    if pc is None:
        errs.append('找不到 %s' % prefab.relative_to(root))
        pc = []
    else:
        uidx = asset_uuid_index(root)
        # 同一個 clipName 只要有任一筆接好就算接好（SoundManager 會跳過沒接的那筆），
        # 共用清單常留著同名的空欄位佔位
        wired = {n for n, u in pc if u and u in uidx}
        empty = [n for n, u in pc if not u and n not in wired]
        dangling = [n for n, u in pc if u and u not in uidx and n not in wired]
        for label, items in (('沒有接音檔', empty), ('的 audioClip 指到不存在的資產', dangling)):
            mine, others = split_severity(items, own_keys)
            if mine:
                errs.append('prefab 有 %d 筆「這台遊戲的」clip %s：%s'
                            % (len(mine), label, '、'.join(mine[:8])))
            if others:
                warns.append('prefab 有 %d 筆共用/舊 clip %s：%s…'
                             '（共用清單在參考專案也多半是空的，只是佔名字；'
                             '只有這台真的要播才需要接）'
                             % (len(others), label, '、'.join(others[:6])))
        # 只有「真的接了音檔」的才算重複；沒接的空欄位在 SoundManager 會被跳過
        dup = {}
        for n, u in pc:
            if u:
                dup[n] = dup.get(n, 0) + 1
        dups = [k for k, v in dup.items() if v > 1]
        if dups:
            errs.append('prefab 有重複 clipName（後面的會蓋掉前面）：%s' % '、'.join(dups))
        mine_ok = [n for n, u in pc if n in own_keys and u and u in uidx]
        if own_keys and len(mine_ok) == len(own_keys & {n for n, _ in pc}):
            oks.append('prefab 裡這台遊戲的 %d 筆 clip 全部指到存在的音檔' % len(mine_ok))

    mixer = sorted(L.sound_dir(root).glob('AudioMixer*.json'))
    mix_clips = {}
    if not mixer:
        errs.append('找不到 assets/Game/game/Sound/AudioMixer*.json'
                    ' -> 全部 clip 走預設值（volume 1、不 loop、無群組）')
    else:
        if len(mixer) > 1:
            warns.append('有 %d 份 AudioMixer json，場景只會載一份：%s'
                         % (len(mixer), '、'.join(p.name for p in mixer)))
        mix_clips = L.load_json(mixer[0]).get('Clips', {})
        oks.append('%s：%d 筆 clip 設定' % (mixer[0].name, len(mix_clips)))
        # ⚠️ mixer json 的 key 是「音檔資產名」，不是 clipName
        # （SoundManager.play 走 playMixerClip(audioClip.name)）
        asset_name = {}   # clipName -> 資產名
        for n, u in pc:
            if u and u in uidx:
                asset_name[n] = Path(uidx[u]).stem
        bad_key = [k for k in mix_clips
                   if k in asset_name and asset_name[k] != k]
        if bad_key:
            errs.append('mixer json 有 %d 個 key 是 clipName 而不是音檔資產名，'
                        '這些設定不會生效：%s'
                        % (len(bad_key), '、'.join(bad_key[:8])))
        no_setting = sorted({a for a in asset_name.values()} - set(mix_clips))
        if no_setting:
            warns.append('有音檔、mixer json 沒設定（會用預設值 volume 1 / 不 loop）%d 筆：%s'
                         % (len(no_setting), '、'.join(no_setting[:10])))

    # 4 loop
    try:
        man = L.load_manifest(root)
    except SystemExit:
        man = None
        warns.append('沒有 audio_manifest.json，跳過 loop / 保留 key 檢查')
    if man:
        ov = L.load_overrides(root)
        for c in man['clips']:
            if not c['has_file']:
                continue
            stem = c.get('asset_stem') or c['stem']
            spec_ov = ov.get(stem) or ov.get(c['key']) or {}
            want_loop = spec_ov.get('loop', -1 if c['loop'] else 0)
            got_loop = mix_clips.get(stem, {}).get('loop')
            if 'loop' in spec_ov:
                if got_loop != want_loop:
                    errs.append('`%s` overrides 要 loop=%r，但 mixer json 是 %r'
                                % (stem, want_loop, got_loop))
            elif c['loop'] and got_loop != -1:
                errs.append('`%s` 規格是 LOOP，但 mixer json（key=資產名）的 loop 不是 -1'
                            '（只會播一次）' % stem)
            if c['key'] in L.RESERVED_KEYS:
                warns.append('`%s` 撞到底層保留 key（%s）'
                             % (c['key'], L.RESERVED_KEYS[c['key']]))
        names_in_prefab = {n for n, _ in pc}
        for alias, spec in sorted(aliases.items()):
            why = L.RESERVED_KEYS.get(alias, spec.get('_why', ''))
            if alias in names_in_prefab:
                oks.append('alias `%s` -> `%s`%s'
                           % (alias, spec.get('target'), '（%s）' % why if why else ''))
            else:
                errs.append('alias `%s` 不在 clip 清單裡，請重跑 update_clip_list.py --apply'
                            % alias)

    # 5 場景接線
    wired, why = scene_mixer_wired(root)
    if wired is None:
        warns.append(why)
    elif not wired:
        errs.append('%s -> 混音設定完全沒生效' % why)
    else:
        oks.append(why)
        if mixer:
            want = L.read_meta_uuid(mixer[0])
            scene = L.main_scene(root)
            if want and want not in scene.read_text(encoding='utf-8'):
                errs.append('場景接的 json 不是 %s（uuid 對不上）' % mixer[0].name)

    # 5b 場景上的 AudioClipContainer：--bgm scene 的音檔要掛在這裡，
    #    否則它們既不在 bundle prefab、也沒人餵給 SoundManager -> 完全播不到
    scene = L.main_scene(root)
    if man and scene:
        outside = [c for c in man['clips']
                   if c['has_file'] and c.get('asset')
                   and '/%s/' % args.bundle not in c['asset']
                   and not c['asset'].startswith('assets/%s/' % args.bundle)]
        if outside:
            try:
                cont_id = L.script_type_id(root, CONTAINER_TS)
            except SystemExit:
                cont_id = None
            text = scene.read_text(encoding='utf-8')
            uncovered = [c for c in outside if c['uuid'] not in text]
            if cont_id and cont_id not in text:
                errs.append('有 %d 支音檔放在 bundle 外（%s…），但場景上沒有 AudioClipContainer '
                            '可以餵給 SoundManager -> 這些音完全播不到'
                            % (len(outside), outside[0]['key']))
            elif uncovered:
                errs.append('有 %d 支音檔放在 bundle 外但場景的 AudioClipContainer 沒引用到，'
                            '播不出來：%s'
                            % (len(uncovered), '、'.join(c['key'] for c in uncovered[:6])))
            else:
                oks.append('bundle 外的 %d 支音檔都掛在場景的 AudioClipContainer 上' % len(outside))

    # 5c 場景 / prefab 的 audioKey 欄位（SymbolShowSetting、DropSymbolPrefabItems…）
    #    那些欄位吃的是 clipName；填成音檔資產名或打錯字都只會印 warn，不會報錯
    names_all = {n for n, _ in pc}
    if scene:
        targets = [scene] + sorted((root / 'assets' / 'Game').rglob('*.prefab'))
        bad, total = [], 0
        for f in targets:
            try:
                data = json.loads(f.read_text(encoding='utf-8'))
            except Exception:
                continue
            for o in data:
                if not isinstance(o, dict):
                    continue
                for field in ('audioKey', 'audioName', 'clipName'):
                    v = o.get(field)
                    if isinstance(v, str) and v and field != 'clipName':
                        total += 1
                        if v not in names_all:
                            bad.append('%s 的 %s="%s"' % (f.name, field, v))
        if bad:
            errs.append('場景/prefab 有 %d 個 audioKey 不在 clip 清單裡（播不出來）：%s'
                        % (len(bad), '、'.join(bad[:6])))
        elif total:
            oks.append('場景/prefab 的 %d 個 audioKey 都對得到 clip' % total)

    # 6 程式引用
    names = {n for n, _ in pc}
    refs = code_refs(root)
    unknown = {k: v for k, v in refs.items() if k not in names and k not in mix_clips}
    if unknown:
        warns.append('程式裡用到不在清單裡的 clip 名（play 只會印 warn，不會報錯）：\n    '
                     + '\n    '.join('`%s`  %s' % (k, v[0]) for k, v in sorted(unknown.items())))
    elif refs:
        oks.append('程式裡 %d 個字面值 clip 名都在清單內' % len(refs))
    if refs:
        warns.append('有 %d 處直接寫字串播音效，建議改用 <G####>_AudioClipNames.ts 的常數：%s'
                     % (sum(len(v) for v in refs.values()),
                        '、'.join(sorted(refs)[:6])))

    print('# 音效接線驗收')
    print('')
    for o in oks:
        print('- ✅ %s' % o)
    for w in warns:
        print('- ⚠️ %s' % w)
    for e in errs:
        print('- ❌ %s' % e)
    print('')
    print('結果：%d 過、%d 警告、%d 錯誤' % (len(oks), len(warns), len(errs)))
    return 1 if errs else 0


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env node
/**
 * 聽牌壓暗＋黑張底：動手前的現況檢查（只讀，不改任何檔案）。
 *
 * 列出六件「看程式看不出來、但決定做法對不對」的事：
 *   1. 場景上的 WheelMaskController：有沒有、mask prefab / maskPool 有沒有接、節點排在 WheelBlock 前還是後
 *      （排在前面 = 黑張畫在圖騰底下；排在後面 = 蓋在圖騰上面，那就不是「底」了）
 *   2. bingo.useWheelMask 的值（各 HostSetting json）——它是報獎用的全域開關，聽牌功能不要靠打開它
 *   3. 黑張 prefab 的尺寸、顏色、透明度、用的圖（default_sprite 是圓角佔位圖，拉伸後四角透明）
 *   4. 每輪的實際格距（左右：相鄰輪中心距；上下：同輪相鄰符號距）與各尺寸下的接縫（重疊／縫隙）
 *   5. 哪些符號有 offClipping 上層複本、哪些有停輪動畫（決定壓暗要不要處理複本與動畫）
 *   6. 遊戲層 Controller / SymbolShowPrefabController 是否已經有壓暗相關程式
 *
 * 用法（在專案根目錄）：
 *   node .claude/skills/slot-prewin-dim-mask/scripts/inspect_dim_mask_setup.js \
 *     [--scene assets/Game/Scene/Scene_GXXXX_Name.scene] \
 *     [--prefab assets/Game/Prefab/WheelBlock.prefab] \
 *     [--sizes "120x90,124x91"]      # 額外想試算接縫的黑張尺寸
 */
const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
const arg = (k, d = null) => {
  const i = args.indexOf(k);
  return i >= 0 ? args[i + 1] : d;
};
const ROOT = process.cwd();

// ── uuid 壓縮／解壓縮（Cocos 3.x：前 5 碼 hex 保留，其餘每 3 個 hex = 2 個 base64 字元） ──
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function compressUuid(uuid) {
  const hex = uuid.replace(/-/g, '');
  let out = hex.slice(0, 5);
  for (let i = 5; i < 32; i += 3) {
    const v = parseInt(hex.substr(i, 3), 16);
    out += B64[v >> 6] + B64[v & 63];
  }
  return out;
}

function walk(dir, test, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, {withFileTypes: true})) {
    if (e.name === 'node_modules' || e.name.startsWith('.')) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, test, out);
    else if (test(e.name, p)) out.push(p);
  }
  return out;
}
const rel = p => path.relative(ROOT, p).replace(/\\/g, '/');
const load = p => (p && fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, 'utf8')) : null);

// 腳本 uuid（壓縮後）→ 類別檔名；資源 uuid → 路徑
const scriptByType = {};
const assetByUuid = {};
for (const m of walk(path.join(ROOT, 'assets'), n => n.endsWith('.meta'))) {
  try {
    const u = JSON.parse(fs.readFileSync(m, 'utf8')).uuid;
    if (!u) continue;
    const file = rel(m).replace(/\.meta$/, '');
    assetByUuid[u] = file;
    if (file.endsWith('.ts')) scriptByType[compressUuid(u)] = path.basename(file, '.ts');
  } catch (_) { /* ignore */ }
}
const typeOf = t => scriptByType[t] || t;

const scenePath =
  arg('--scene') ||
  walk(path.join(ROOT, 'assets/Game'), n => n.endsWith('.scene'))[0];
const prefabPath =
  arg('--prefab') ||
  walk(path.join(ROOT, 'assets/Game'), n => /^WheelBlock.*\.prefab$/.test(n))[0];
const scene = load(scenePath);
const wheelPrefab = load(prefabPath);
console.log(`scene : ${scenePath ? rel(scenePath) : '(找不到)'}`);
console.log(`prefab: ${prefabPath ? rel(prefabPath) : '(找不到)'}\n`);
if (!scene) process.exit(1);

const nodePath = id => {
  const parts = [];
  while (id !== undefined && id !== null && scene[id]) {
    parts.unshift(scene[id]._name || '(prefab)');
    id = scene[id]._parent ? scene[id]._parent.__id__ : null;
  }
  return parts.join('/');
};
const prefabInstanceName = n => {
  if (n._name || !n._prefab) return n._name;
  const pi = scene[n._prefab.__id__];
  const asset = pi && pi.asset && pi.asset.__uuid__;
  return `(prefab ${asset && assetByUuid[asset] ? path.basename(assetByUuid[asset]) : asset})`;
};

// ── 1. WheelMaskController ──
console.log('== 1. 場景上的 WheelMaskController ==');
const maskCtrls = scene
  .map((o, i) => ({o, i}))
  .filter(({o}) => o && typeof o.__type__ === 'string' && typeOf(o.__type__) === 'WheelMaskController');
let maskPrefabPath = null;
if (maskCtrls.length === 0) {
  console.log('  （沒有）→ 要先在 GameRoot 下、WheelBlock 之前建一個節點，掛 WheelMaskController + SpawnPool，');
  console.log('    並接到 AwardController.showFrameObj[0].wheelMaskControllerEx（用 Cocos MCP）');
}
for (const {o, i} of maskCtrls) {
  const nodeId = o.node.__id__;
  const maskUuid = o.mask && o.mask.__uuid__;
  maskPrefabPath = maskUuid ? assetByUuid[maskUuid] || maskUuid : null;
  const pool = o.maskPool && o.maskPool.__id__ !== undefined ? scene[o.maskPool.__id__] : null;
  console.log(`  #${i} 節點 ${nodePath(nodeId)}`);
  console.log(`     mask     = ${maskPrefabPath || '（沒接）'}`);
  console.log(`     maskPool = ${pool ? typeOf(pool.__type__) + '（已接）' : '（沒接）'}`);
  const refBy = scene
    .map((x, j) => ({x, j}))
    .filter(({x}) => x && x.wheelMaskControllerEx && x.wheelMaskControllerEx.__id__ === i);
  console.log(`     被 ${refBy.length ? refBy.map(({x, j}) => `#${j} ${typeOf(x.__type__)}.wheelMaskControllerEx`).join('、') : '（沒有任何 ShowFrameObj 參照 → 程式從 awardController.showFrameObj[0] 拿不到它）'}`);
  const parent = scene[scene[nodeId]._parent.__id__];
  const sibs = parent._children.map(c => ({id: c.__id__, name: prefabInstanceName(scene[c.__id__])}));
  const me = sibs.findIndex(s => s.id === nodeId);
  const wb = sibs.findIndex(s => /WheelBlock(?!BG)/i.test(s.name));
  console.log(`     同層順序：${sibs.map((s, k) => (k === me ? `[${s.name}]` : s.name)).join(', ')}`);
  if (wb >= 0) {
    console.log(me < wb
      ? '     → 排在 WheelBlock 之前：黑張畫在圖騰「底下」✔'
      : '     → 排在 WheelBlock 之後：黑張會「蓋住」圖騰，若要當底版要調整節點順序');
  } else {
    console.log('     → 同層找不到名稱含 WheelBlock 的節點（可能是沒改名的 prefab 實例），請在 Editor 確認它在轉輪之前');
  }
}
console.log();

// ── 2. useWheelMask ──
console.log('== 2. bingo.useWheelMask（報獎用的全域開關，聽牌功能不要靠它）==');
for (const f of walk(path.join(ROOT, 'assets/Game'), n => /HostSetting.*\.json$/i.test(n))) {
  const m = fs.readFileSync(f, 'utf8').match(/"useWheelMask"\s*:\s*(true|false)/);
  console.log(`  ${rel(f)}: ${m ? m[1] : '（沒有這個欄位）'}`);
}
console.log('  ※ true 時 AwardSet.init 會為每格 spawnMask、報獎時 showWheelMask 會用同一批黑張；聽牌自己生的黑張與它分開管理\n');

// ── 3. 黑張 prefab ──
const DEFAULT_SPRITE = '57520716-48c8-4a19-8acf-41c9f8777fb0';
const SPLASH = '7d8f9b89-4fd1-4c9f-a3ab-38ec7cded7ca';
let maskSize = null;
console.log('== 3. 黑張 prefab ==');
const mp = maskPrefabPath && fs.existsSync(path.join(ROOT, maskPrefabPath)) ? load(path.join(ROOT, maskPrefabPath)) : null;
if (!mp) console.log('  （找不到 prefab 檔）');
else {
  for (const o of mp) {
    if (!o) continue;
    if (o.__type__ === 'cc.UITransform') {
      maskSize = o._contentSize;
      console.log(`  尺寸 ${o._contentSize.width}×${o._contentSize.height}，錨點 (${o._anchorPoint.x}, ${o._anchorPoint.y})`);
    }
    if (o.__type__ === 'cc.Sprite') {
      const f = o._spriteFrame && o._spriteFrame.__uuid__ ? o._spriteFrame.__uuid__.split('@')[0] : null;
      const name = f === DEFAULT_SPRITE ? 'default_sprite（Cocos 內建圓角佔位圖：四角透明，拉伸後圓角跟著放大）✘ 建議換 default_sprite_splash'
        : f === SPLASH ? 'default_sprite_splash（2×2 純白，直角）✔'
        : f ? assetByUuid[f] || f : '（沒有圖）';
      console.log(`  圖 ${name}`);
      console.log(`  顏色 rgba(${o._color.r},${o._color.g},${o._color.b},${o._color.a})，sizeMode ${o._sizeMode}${o._sizeMode === 0 ? '（Custom，換圖不會改尺寸）' : '（不是 Custom：換圖會把尺寸改成圖的大小）'}，type ${o._type}`);
    }
    if (o.__type__ === 'cc.UIOpacity') console.log(`  UIOpacity ${o._opacity}（半透明時重疊處會比較深）`);
  }
}
console.log();

// ── 4. 格距與接縫 ──
console.log('== 4. 每輪實際格距與接縫 ==');
if (!wheelPrefab) console.log('  （找不到 WheelBlock prefab）');
else {
  const comp = (n, t) => (n._components || []).map(c => wheelPrefab[c.__id__]).find(c => c && c.__type__ === t);
  // 有 symbolAry 的元件 = 轉輪
  const wheels = wheelPrefab
    .filter(o => o && Array.isArray(o.symbolAry) && o.symbolAry.length > 1 && o.node)
    .map(o => {
      const n = wheelPrefab[o.node.__id__];
      const parent = n._parent ? wheelPrefab[n._parent.__id__] : null;
      const symNodes = o.symbolAry.map(r => wheelPrefab[wheelPrefab[r.__id__].node.__id__]);
      const ys = symNodes.map(s => s._lpos.y);
      const pitchY = Math.abs(ys[0] - ys[1]);
      const ut = comp(symNodes[0], 'cc.UITransform');
      return {
        name: n._name,
        x: n._lpos.x + (parent && parent._lpos ? parent._lpos.x : 0),
        pitchY,
        count: symNodes.length,
        symbolSize: ut ? `${ut._contentSize.width}×${ut._contentSize.height}` : '?',
      };
    })
    .sort((a, b) => a.x - b.x);
  wheels.forEach((w, k) => {
    const dx = k > 0 ? (w.x - wheels[k - 1].x).toFixed(0) : '-';
    console.log(`  ${w.name.padEnd(8)} x=${String(w.x).padStart(5)}  與左輪距 ${String(dx).padStart(4)}  上下格距 ${w.pitchY}  符號節點 ${w.symbolSize}（${w.count} 張）`);
  });
  const pitchesX = wheels.slice(1).map((w, k) => Math.round(w.x - wheels[k].x));
  const pitchesY = [...new Set(wheels.map(w => w.pitchY))];
  const sizes = [];
  if (maskSize) sizes.push([maskSize.width, maskSize.height, '目前']);
  sizes.push([Math.min(...pitchesX), Math.min(...pitchesY), '最小格距（不重疊，但寬間距處留縫）']);
  sizes.push([Math.max(...pitchesX), Math.max(...pitchesY), '最大格距（不留縫，但窄間距處重疊）']);
  for (const s of (arg('--sizes') || '').split(',').filter(Boolean)) {
    const [w, h] = s.split('x').map(Number);
    if (w && h) sizes.push([w, h, '試算']);
  }
  console.log('  ── 各尺寸的接縫（正數 = 重疊 px、負數 = 縫隙 px）──');
  for (const [w, h, label] of sizes) {
    const xs = pitchesX.map(p => w - p);
    const ys = pitchesY.map(p => h - p);
    console.log(`  ${w}×${h}（${label}）：左右 [${xs.join(', ')}]  上下 [${ys.join(', ')}]`);
  }
  if (new Set(pitchesX).size > 1) {
    console.log('  ※ 各輪左右間距不一致 → 單一 prefab 尺寸無法每個接縫都剛好；要完全貼齊需依每輪間距在程式裡設黑張寬度');
  }
}
console.log();

// ── 5. 符號的 offClipping 與停輪動畫 ──
console.log('== 5. 符號顯示設定（決定壓暗要處理哪些層）==');
const ref = r => (r && r.__id__ !== undefined ? scene[r.__id__] : r);
const shows = scene.filter(o => o && 'offClipping' in o && 'symbolID' in o);
const drops = scene.filter(o => o && 'isOffClipping' in o && 'symbolID' in o);
const showOff = shows.filter(o => o.offClipping).map(o => o.symbolID);
const dropOff = drops.filter(o => o.isOffClipping).map(o => o.symbolID);
const stopAnim = shows.filter(o => {
  const a = ref(o.wheelStopAnimaPrefabArgs);
  return a && a.animaPrefabTform;
}).map(o => o.symbolID);
console.log(`  Show 套 offClipping 上層複本：${showOff.join(', ') || '無'}`);
console.log(`  Drop 套 offClipping 上層複本：${dropOff.join(', ') || '無'}`);
console.log(`  有停輪動畫（Show 套 wheelStopAnimaPrefabArgs）：${stopAnim.join(', ') || '無'}`);
console.log('  ※ 只有上面「沒有上層複本」的符號，壓下層真身 Sprite 就等於壓到畫面上那張；有複本的（通常是 Scatter）要另外處理或排除\n');

// ── 6. 遊戲層既有程式 ──
console.log('== 6. 遊戲層既有程式 ==');
const gameScripts = walk(path.join(ROOT, 'assets/Game/Script'), n => n.endsWith('.ts'));
const find = re => gameScripts.filter(f => re.test(fs.readFileSync(f, 'utf8'))).map(rel);
console.log(`  覆寫 showPrewin：${find(/(public|protected)\s+showPrewin\s*\(/).join(', ') || '無'}`);
console.log(`  已有壓暗程式（prewinDimColor / applyPrewinDim）：${find(/prewinDimColor|applyPrewinDim/).join(', ') || '無'}`);
console.log(`  已有聽牌黑張（_prewinMasks）：${find(/_prewinMasks/).join(', ') || '無'}`);
console.log(`  SymbolShowPrefabController 子類：${find(/extends\s+SymbolShowPrefabController/).join(', ') || '無（停輪動畫壓暗需要它提供 getStopAnimNode / undim 掛勾）'}`);

# 參考實作（WildFrontier G1028，2026-10-08 使用者驗收版本）

把 `GXXXX` 換成目標遊戲前綴。現役程式在 `assets/Game/Script/G1028_WheelBlockController.ts`、`G1028_SymbolShowPrefabController.ts`，有出入時以現役程式為準。

目錄：
1. Controller 端：欄位與 import
2. Controller 端：壓暗／還原／黑張
3. Controller 端：接進 showPrewin / hidePrewin / spinAll
4. SymbolShowPrefabController 端：三個掛勾
5. 黑張 prefab 設定

---

## 1. Controller 端：欄位與 import

`GXXXX_WheelBlockController extends WheelBlockController`（WheelBlock 上一定有掛的那個元件；轉輪本身常常掛的是底層 `Wheel`，覆寫 `GXXXX_Wheel` 不會跑）。

```ts
import {_decorator, CCFloat, Color, Node, tween, UIRenderer, Vec2, Vec3} from 'cc';
import {getNodeSpaceFromOtherNode} from 'db://assets/CommonModule/Script/Utility/NodeProperty';
import type {WheelMaskController} from 'db://assets/SlotModule/Wheel/WheelMaskController';
// 只用於型別轉換：用 import type 斷開循環相依（Show 套那支也會 import 本類別）
import type GXXXX_SymbolShowPrefabController from './GXXXX_SymbolShowPrefabController';
import {SlotGameMediator} from 'db://assets/SlotModule/Define/SlotGameMediator';
```

`SCATTER_ID`、`_prewinPlaying`（showPrewin～hidePrewin 之間為 true）、`_prewinAry`、`hasPrewinAfter()` 是聽牌既有邏輯，沒有的話見 `slot-prewin-effect` skill 的參考實作。

## 2. Controller 端：壓暗／還原／黑張

```ts
  @property({
    tooltip:
      '聽牌時「聽的那一輪」以外的壓暗顏色（乘在原圖上；白色 = 不壓暗；已停輪的 Scatter 不壓）。最後一個聽牌輪停穩時還原',
  })
  public prewinDimColor: Color = new Color(100, 100, 100, 255);

  /**
   * 被壓暗的 renderer → 壓暗前的顏色（還原用；已記過的不重記，避免把暗色當原色）。
   * 壓暗對象只改顏色、不動 active：
   * - 下層真身 Symbol.node 上的 Sprite（非 Scatter 沒有上層複本，真身就是畫面上那張）
   * - Show 套在該格的停輪動畫節點，整棵子樹的 renderer（spine 常掛在子節點）
   * 停輪動畫節點是物件池重用的：收掉時由 Show 套呼叫 undimNode 先還原。
   */
  private _dimmedRenderers: Map<UIRenderer, Color> = new Map();

  /** 已壓暗的格子，key = `${輪}_${可視列}`（給「停輪動畫比 showPrewin 晚生」的補壓用） */
  private _dimmedCells: Set<string> = new Set<string>();

  private get showPrefabCtrl(): GXXXX_SymbolShowPrefabController {
    return SlotGameMediator.instance.awardController?.showFrameObj?.[0]
      ?.symbolShowPrefabController as GXXXX_SymbolShowPrefabController;
  }

  /**
   * 墊在圖騰底下的黑張，key = `${輪}_${可視列}`；壓暗的格子才開。
   * 借用場景 WheelMaskController 的 mask prefab／物件池／節點（它排在 WheelBlock 之前 = 畫在圖騰底下），
   * 但不走它的 init/spawnMask/showMask：那套歸 bingo.useWheelMask（報獎用），而且 spawnMask 取的是
   * 「當下」位置，還在轉的輪會偏。節點生了就留著重用（只切 active），每次開都重新定位。
   */
  private _prewinMasks: Map<string, Node> = new Map();
  private _prewinMaskWarned = false;

  private get wheelMaskCtrl(): WheelMaskController {
    return SlotGameMediator.instance.awardController?.showFrameObj?.[0]
      ?.wheelMaskControllerEx;
  }

  private showPrewinMask(wheelIndex: number, visibleRow: number): void {
    const ctrl = this.wheelMaskCtrl;
    const wheel = this.wheelAry[wheelIndex];
    const symbolNode =
      wheel?.symbolAry?.[visibleRow + wheel.outOfTopSymbolAmount]?.node;
    if (!ctrl?.mask || !ctrl.maskPool || !symbolNode || !wheel.node.parent) {
      if (!this._prewinMaskWarned) {
        this._prewinMaskWarned = true;
        console.warn(
          '[prewinDim] WheelMaskController 的 mask／maskPool 沒接（或找不到 awardController.showFrameObj[0].wheelMaskControllerEx），聽牌只壓暗、不墊黑張'
        );
      }
      return;
    }

    const key = `${wheelIndex}_${visibleRow}`;
    let node = this._prewinMasks.get(key);
    if (!node?.isValid) {
      node = ctrl.maskPool.spawn(ctrl.mask.data);
      if (!node) return;
      node.parent = ctrl.node;
      this._prewinMasks.set(key, node);
    }

    // 取這一格「靜止時」的位置：轉動時移動的是轉輪節點（符號在轉輪內的位置不變），
    // 所以用 originWheelPos 代替轉輪當下的位置，還在轉的輪也能對準格子。
    const p = symbolNode.position;
    const sc = wheel.node.scale;
    const restLocal = new Vec3(
      wheel.originWheelPos.x + p.x * sc.x,
      wheel.originWheelPos.y + p.y * sc.y,
      0
    );
    node.setPosition(
      getNodeSpaceFromOtherNode(ctrl.node, wheel.node.parent, restLocal)
    );
    node.active = true;
  }

  private hidePrewinMask(wheelIndex: number, visibleRow: number): void {
    const node = this._prewinMasks.get(`${wheelIndex}_${visibleRow}`);
    if (node?.isValid) node.active = false;
  }

  private dimRenderer(r: UIRenderer): void {
    if (!r?.isValid) return;
    if (!this._dimmedRenderers.has(r)) this._dimmedRenderers.set(r, r.color.clone());
    r.color = this.prewinDimColor;
  }

  /** 把一個動畫節點（整棵子樹）壓暗 */
  private dimNode(node: Node | null): void {
    if (!node?.isValid) return;
    for (const r of node.getComponentsInChildren(UIRenderer)) this.dimRenderer(r);
  }

  /** 還原一個節點（整棵子樹）的壓暗。給 Show 套在停輪動畫節點還給物件池前呼叫 */
  public undimNode(node: Node | null): void {
    if (!node?.isValid || this._dimmedRenderers.size === 0) return;
    for (const r of node.getComponentsInChildren(UIRenderer)) {
      const color = this._dimmedRenderers.get(r);
      if (!color) continue;
      r.color = color;
      this._dimmedRenderers.delete(r);
    }
  }

  /**
   * 只有正在聽的那一輪（listeningWheel）是亮的，其他輪壓暗。
   * - 已停好的輪（索引較小）：可視範圍內的非 Scatter 壓暗（真身＋停輪動畫＋黑張）；Scatter 維持亮。
   * - 還在轉的輪（索引較大）：整輪所有圖騰壓暗（含上方緩衝格，轉進畫面時才不會亮一張）＋可視格黑張。
   * - 聽的那一輪：還原（它上一次 showPrewin 時還是「還在轉的輪」、被整輪壓暗過）。
   * 每次 showPrewin 都呼叫：聽牌移到下一輪時，上一個聽牌輪變成已停輪而壓暗，新的聽牌輪變亮。
   */
  private applyPrewinDim(listeningWheel: number): void {
    const C = GXXXX_WheelBlockController;
    for (let w = 0; w < this.wheelAry.length; w++) {
      const wheel = this.wheelAry[w];
      if (!wheel) continue;

      if (w === listeningWheel) {
        this.undimWheel(w);
        continue;
      }

      const visibleCount = wheel.visibleSymbolAmount ?? 0;

      if (w > listeningWheel) {
        for (const symbol of wheel.symbolAry ?? []) this.dimRenderer(symbol?.sprite);
        for (let s = 0; s < visibleCount; s++) this.showPrewinMask(w, s);
        continue;
      }

      for (let s = 0; s < visibleCount; s++) {
        const symbol = wheel.symbolAry?.[s + wheel.outOfTopSymbolAmount];
        if (!symbol?.sprite || symbol.symbolInfo?.symbolID === C.SCATTER_ID) {
          this.hidePrewinMask(w, s);
          continue;
        }
        this._dimmedCells.add(`${w}_${s}`);
        this.dimRenderer(symbol.sprite);
        this.dimNode(this.showPrefabCtrl?.getStopAnimNode?.(w, s));
        this.showPrewinMask(w, s);
      }
    }
  }

  /** 還原一整輪（圖騰真身＋可視格停輪動畫＋黑張） */
  private undimWheel(wheelIndex: number): void {
    const wheel = this.wheelAry[wheelIndex];
    if (!wheel) return;
    for (let s = 0; s < (wheel.visibleSymbolAmount ?? 0); s++) {
      this.hidePrewinMask(wheelIndex, s);
    }
    if (this._dimmedRenderers.size === 0) return;
    for (const symbol of wheel.symbolAry ?? []) {
      const r = symbol?.sprite;
      const color = r ? this._dimmedRenderers.get(r) : null;
      if (!color) continue;
      r.color = color;
      this._dimmedRenderers.delete(r);
    }
    const visibleCount = wheel.visibleSymbolAmount ?? 0;
    for (let s = 0; s < visibleCount; s++) {
      this._dimmedCells.delete(`${wheelIndex}_${s}`);
      this.undimNode(this.showPrefabCtrl?.getStopAnimNode?.(wheelIndex, s));
    }
  }

  /**
   * Show 套剛對 wheelIndex 生完停輪動畫時呼叫：已壓暗的格子把新生的動畫也壓暗。
   * 補「showPrewin(下一輪) 比這一輪的停輪動畫先到」的順序 —— 那時 applyPrewinDim 還拿不到動畫節點。
   */
  public onStopAnimSpawned(wheelIndex: number): void {
    if (!this._prewinPlaying || this._dimmedCells.size === 0) return;
    const visibleCount = this.wheelAry[wheelIndex]?.visibleSymbolAmount ?? 0;
    for (let s = 0; s < visibleCount; s++) {
      if (!this._dimmedCells.has(`${wheelIndex}_${s}`)) continue;
      this.dimNode(this.showPrefabCtrl?.getStopAnimNode?.(wheelIndex, s));
    }
  }

  /** 全部還原（包含已還給物件池的節點）並收掉黑張 */
  private restoreDimmedSymbols(): void {
    this._dimmedRenderers.forEach((color, r) => {
      if (r?.isValid) r.color = color;
    });
    this._dimmedRenderers.clear();
    this._dimmedCells.clear();
    this._prewinMasks.forEach(node => {
      if (node?.isValid) node.active = false;
    });
  }
```

## 3. Controller 端：接進 showPrewin / hidePrewin / spinAll

```ts
  public spinAll(PlayMode: GamePlayMode): Promise<void> {
    // 保險：上一手的 hidePrewin 沒來，起轉前強制還原
    if (this._dimmedRenderers.size > 0) {
      console.error(
        `[prewinDim] 起轉時仍有 ${this._dimmedRenderers.size} 個壓暗未還原（hidePrewin 沒收到），強制還原`
      );
      this.restoreDimmedSymbols();
    }
    return super.spinAll(PlayMode);
  }

  public showPrewin(wheelIndex: number): void {
    super.showPrewin(wheelIndex);
    // …既有的變速、縮放…
    if (!this._prewinPlaying) this._loopingCells.clear();
    this._prewinPlaying = true;

    // 只有聽的這一輪是亮的。要放在下面任何 `if (!hasNew) return;` 之類的提早 return 之前
    this.applyPrewinDim(wheelIndex);

    // …既有的 Scatter Loop 邏輯…
  }

  public hidePrewin(wheelIndex: number): void {
    super.hidePrewin(wheelIndex);
    if (this.hasPrewinAfter(wheelIndex)) return; // 後面還有聽牌輪 → 不收
    this._prewinPlaying = false;
    // …既有的縮放復原…
    this.restoreDimmedSymbols();
    // …既有的收 Scatter Loop…
  }
```

## 3b. 延伸：cascade 消牌時壓暗

Controller 端加一支 public 方法，`restoreDimmedSymbols` 改成 public：

```ts
  /**
   * cascade 消牌時壓暗：這一輪「不消除、也不在 keepBright 裡」的可視格，非 Scatter 壓暗＋墊黑張。
   * 與聽牌壓暗共用同一套顏色、記錄與黑張；兩者不會同時發生。
   */
  public dimForClear(removePos: number[][], keepBright: Array<[number, number]>): void {
    const C = GXXXX_WheelBlockController;
    const keep = new Set(keepBright.map(([w, s]) => `${w}_${s}`));
    for (let w = 0; w < this.wheelAry.length; w++) {
      const wheel = this.wheelAry[w];
      const visibleCount = wheel?.visibleSymbolAmount ?? 0;
      for (let s = 0; s < visibleCount; s++) {
        if (removePos?.[w]?.[s] === 1 || keep.has(`${w}_${s}`)) continue;
        const symbol = wheel.symbolAry?.[s + wheel.outOfTopSymbolAmount];
        if (!symbol?.sprite || symbol.symbolInfo?.symbolID === C.SCATTER_ID) continue;
        this.dimRenderer(symbol.sprite);
        this.dimNode(this.showPrefabCtrl?.getStopAnimNode?.(w, s));
        this.showPrewinMask(w, s);
      }
    }
  }
```

cascade 流程端（WildFrontier 是 `Feature/GXXXX_Combo.ts` 的 `playCombo`）：

```ts
import type {GXXXX_WheelBlockController} from '../GXXXX_WheelBlockController';

  // startClear 之前
  const wheelCtrl = this.dropModule?.wheelBlockController as GXXXX_WheelBlockController;
  wheelCtrl?.dimForClear?.(
    bingoSymbol,                                                   // RemovePos，[輪][可視列]
    this.postWinChanges.map(c => [c.Pos[0], c.Pos[1]] as [number, number]) // 中獎不消除的格子
  );
  // 消除的 Bingo 播到 CLEAR_DIM_RESTORE_RATIO（檔頭常數，WildFrontier = 2/3）時還原
  // （getBingoAnimDuration 內含 runtime data 未載入時的 fallback）
  const dimRestoreDelay =
    (this.dropSymbolPrefabCtrl?.getBingoAnimDuration(bingoSymbol) ?? 0) * CLEAR_DIM_RESTORE_RATIO;
  waitForSeconds(dimRestoreDelay).then(() => {
    // 被新的一手接手就不動：新的一手可能已經在聽牌壓暗，還原會把它清掉
    if (!this.isStaleEpoch(epoch)) wheelCtrl?.restoreDimmedSymbols?.();
  });
  const clearDone = this.startClear(bingoSymbol);
  // …金框 Bingo → Wild 鏈…
  await Promise.all([clearDone, postWinChainDone]);
  if (this.isStaleEpoch(epoch)) return;
  wheelCtrl?.restoreDimmedSymbols?.(); // 保險：正常已在 Bingo 播到該比例時還原
  // …掉落…
```

其他專案的 cascade 流程名稱不同時，找「呼叫 `DropModule.setClearEffect`（消除演出）」與「呼叫 `dropSingleWheel`／`drop`（掉落）」的位置：前者之前壓暗、後者之前還原。「中獎但不消除」的格子依該遊戲協定決定（沒有就傳空陣列）。

## 4. SymbolShowPrefabController 端：三個掛勾

`GXXXX_SymbolShowPrefabController extends SymbolShowPrefabController`。沒有這個子類的話要新建，並確認場景上 SymbolShowPrefab 節點掛的是它（用 MCP 換腳本，或請使用者在 Inspector 換）。

```ts
import {GXXXX_WheelBlockController} from './GXXXX_WheelBlockController';

  /** 這一格目前掛著的一般停輪動畫節點（沒有或已關閉回 null）。給聽牌壓暗用 */
  public getStopAnimNode(wheelIndex: number, visibleRowIdx: number): Node | null {
    const wheel = this.wheelBlockControllerEx?.wheelAry?.[wheelIndex];
    const node =
      this.symbolShowInfoAry?.[wheelIndex]?.[
        visibleRowIdx + (wheel?.outOfTopSymbolAmount ?? 0)
      ]?.wheelStopAnimaPrefabTform;
    return node?.isValid && node.active ? node : null;
  }

  // ① 生完停輪動畫：通知 Controller 補壓（已有 override 的話，加在 super 之後最後面）
  protected spawnWheelStopAnimaPrefab(wheelCtrlIndex: number, wheelIndex: number, sortedSymbolAry: Symbol[]): void {
    super.spawnWheelStopAnimaPrefab(wheelCtrlIndex, wheelIndex, sortedSymbolAry);
    (this.wheelBlockControllerEx as GXXXX_WheelBlockController)?.onStopAnimSpawned?.(wheelIndex);
  }

  // ② 停輪動畫還給物件池之前：先還原顏色（加在 override 最前面）
  protected hideStopAnimaPrefab(wheelIndex: number, sortedIndex: number, showSymbol = false): void {
    const info = this.symbolShowInfoAry?.[wheelIndex]?.[sortedIndex];
    if (!info) return;
    this._undim(info.wheelStopAnimaPrefabTform);
    super.hideStopAnimaPrefab(wheelIndex, sortedIndex, showSymbol);
  }

  // ③ 若有自己直接 despawn 的路徑（例如 _forceDespawn），一樣先 _undim(node)

  private _undim(node: Node | null): void {
    (this.wheelBlockControllerEx as GXXXX_WheelBlockController)?.undimNode?.(node);
  }
```

`wheelBlockControllerEx` 在場景檔裡可能是 null、但透過 `cc.TargetOverrideInfo` 接上（WildFrontier 就是），要用 MCP `component_get_component_info` 看 live 值，不要只看 `.scene`。

## 5. 黑張 prefab 設定

| 項目 | 建議值 | 為什麼 |
|------|--------|--------|
| 圖 | `default_sprite_splash`（`7d8f9b89-4fd1-4c9f-a3ab-38ec7cded7ca@f9941`） | 2×2 純白、直角。`default_sprite`（新建 Sprite 預設圖）是 40×36 圓角佔位圖，四角透明，拉伸後圓角跟著放大 |
| Sprite sizeMode | Custom（0） | 換圖不會把尺寸改成圖的大小 |
| 顏色 | 黑 (0,0,0,255) | 白圖 × 黑 = 黑 |
| UIOpacity | 依美術（WildFrontier 180） | 半透明時兩張重疊處會更深，接縫會出現深色細線 |
| 尺寸 | ≈ 一格的格距（左右 = 相鄰輪中心距、上下 = 同輪符號距） | 用 `inspect_dim_mask_setup.js` 第 4 段試算接縫。WildFrontier 使用者最後選 125×91 |
| 節點位置 | WheelMaskController 節點要排在 WheelBlock **之前** | 之前 = 畫在圖騰底下；之後 = 蓋在圖騰上面 |

改 prefab 的 MCP 步驟見 `pitfalls.md` 第 6 點。

