### 欄位與曲線

```ts
  @property({type: CCFloat, tooltip: '聽牌起始速度（px/幀）。<=0 時沿用進聽牌前的轉速'})
  public prewinStartSpeed = 0;

  @property({type: CCFloat, tooltip: '聽牌峰值速度（px/幀），上限約圖距×0.9。<=0 時 = 起始速度（不加速）'})
  public prewinPeakSpeed = 0;

  @property({type: CCFloat, tooltip: '聽牌最低速度（px/幀），煞完後換結果圖也用它。<=0 時用 Prewin 設定的 wheelRotateSpeed'})
  public prewinEndSpeed = 6;

  @property({type: CCFloat, tooltip: '起始→峰值這段佔聽牌時長的比例（0~0.9），其餘用來煞車'})
  public prewinAccelRatio = 0.15;

  private static readonly MAX_SPEED_RATIO = 0.9;

  private _speedCurves: Map<number, {
    from: number; peak: number; to: number;
    accelSteps: number; totalSteps: number; step: number;
  }> = new Map();

  /** 頭尾都緩。quadOut 會在前段就把速度降掉大半，看不出由快變慢 */
  private static smoothstep(t: number): number {
    return t * t * (3 - 2 * t);
  }

  /** 必須在 super.showPrewin 之後呼叫（super 會蓋掉 rotationSpeed） */
  private startPrewinSpeedCurve(wheelIndex: number, fromSpeed: number): void {
    const wheel = this.wheelAry[wheelIndex];
    if (!wheel) return;

    const prewinInfo = this.getRotateSetting(GamePlayMode.Prewin) as WheelRotateSetting;
    const duration = prewinInfo?.wheelStopGapTime ?? 0;      // 跟底層的停輪延遲共用同一個值
    const totalSteps = Math.round(duration / TimeManager.FixedTimestep);
    const to = this.prewinEndSpeed > 0 ? this.prewinEndSpeed : wheel.rotationSpeed;
    if (totalSteps <= 0 || to <= 0) return;

    const from = this.prewinStartSpeed > 0 ? this.prewinStartSpeed : fromSpeed;
    let peak = this.prewinPeakSpeed > 0 ? Math.max(this.prewinPeakSpeed, from) : from;
    const spacing = Math.max(Math.abs(wheel.rotationDistance.x), Math.abs(wheel.rotationDistance.y));
    if (spacing > 0) {
      const maxSpeed = spacing * GXXXX_WheelBlockController.MAX_SPEED_RATIO;
      if (peak > maxSpeed) {
        console.warn(`[prewinSpeed] 峰值速度 ${peak} 超過圖距 ${spacing} 的 0.9 倍，會跳格，改用 ${maxSpeed}`);
        peak = maxSpeed;
      }
    }

    const ratio = Math.min(Math.max(this.prewinAccelRatio, 0), 0.9);
    this._speedCurves.set(wheelIndex, {
      from: Math.min(from, peak), peak, to,
      accelSteps: Math.round(totalSteps * ratio), totalSteps, step: 0,
    });
    // 第一步要到下一次 fixedUpdate 才會套用，先設成起始速度，避免這一幀掉到 Prewin 速度
    wheel.setRotationSpeed(from > 0 ? from : peak);
  }

  /** 在轉輪移動「之前」更新速度；煞車回彈自帶速度，不受影響 */
  public fixedUpdate(): void {
    if (this._speedCurves.size > 0) this.stepPrewinSpeedCurves();
    super.fixedUpdate();
  }

  private stepPrewinSpeedCurves(): void {
    this._speedCurves.forEach((c, wheelIndex) => {
      const wheel = this.wheelAry[wheelIndex];
      const status = wheel?.wheelStatus;
      if (!wheel || status === Status.Idle || status === Status.Stop || status === Status.BreakToBound) {
        this._speedCurves.delete(wheelIndex);
        return;
      }
      c.step++;
      let speed: number;
      if (c.step <= c.accelSteps) {
        speed = c.from + (c.peak - c.from) * GXXXX_WheelBlockController.smoothstep(c.step / c.accelSteps);
      } else {
        const raw = Math.min((c.step - c.accelSteps) / (c.totalSteps - c.accelSteps), 1);
        speed = c.peak + (c.to - c.peak) * GXXXX_WheelBlockController.smoothstep(raw);
        if (raw >= 1) this._speedCurves.delete(wheelIndex); // rotationSpeed 停在最低速度，給換結果圖用
      }
      wheel.setRotationSpeed(speed);
    });
  }
