}
console.log();

// ── 4. 格距與接縫 ──
console.log('== 4. 每輪實際格距與接縫 ==');
if (!wheelPrefab) console.log('  （找不到 WheelBlock prefab）');
else {
  const comp = (n, t) => (n._components || []).map(c => wheelPrefab[c.__id__]).find(c => c && c.__type__ === t);
  // 有 symbolAry 的元件 = 轉輪
  const wheels = wheelPrefab
    .filter(o => o && Array.isArray(o.symbolAry) && o.symbolAry.length > 1 && o.node)
    .map(o => {
      const n = wheelPrefab[o.node.__id__];
      const parent = n._parent ? wheelPrefab[n._parent.__id__] : null;
      const symNodes = o.symbolAry.map(r => wheelPrefab[wheelPrefab[r.__id__].node.__id__]);
