#!/usr/bin/env node
/**
 * validate_patterns.cjs
 *
 * 驗證 slot-gen/patterns 的完整性，並（可選）用一段 spec 文字模擬
 * feature-composer 的關鍵詞匹配，確認新 pattern 會被命中。
 *
 * 用法（在 slot-gen 目錄下執行；副檔名為 .cjs 因為 slot-gen 是 ESM 套件）：
 *   node .claude/skills/extract-slot-pattern/scripts/validate_patterns.cjs
 *   node .claude/skills/extract-slot-pattern/scripts/validate_patterns.cjs --match "乘倍輪盤 收集升級 multiplier"
 *   node .claude/skills/extract-slot-pattern/scripts/validate_patterns.cjs --regression
 *
 * 檢查項目：
 *   1. index.json 可解析
 *   2. pattern id 無重複
 *   3. 每個 index 條目對應目錄的 metadata.json / README.md / implementation.ts 都存在
 *   4. metadata.json 可解析且 id 與 index 條目一致
 *   5. （--match）用 tags + specKeywords 算出最高分 pattern，並顯示第二名
 *   6. （--regression）跑 regression-cases.json 的全部查詢，確認：
 *        - 每筆命中預期的 pattern（新 pattern 沒搶走既有的位置）
 *        - 領先幅度足夠（≤5 分會警告：隨時可能被下一個 pattern 搶走）
 *        - 每個 pattern 都有查詢守著（沒有的會列出來建議補）
 *      新增 pattern 時務必把它的代表查詢加進 regression-cases.json。
 */

const fs = require('fs');
const path = require('path');

// 從目前工作目錄往上找 patterns/index.json（支援在 slot-gen 根或子目錄執行）
function findPatternsDir(start) {
    let dir = start;
    for (let i = 0; i < 6; i++) {
        const candidate = path.join(dir, 'patterns', 'index.json');
        if (fs.existsSync(candidate)) return path.join(dir, 'patterns');
        const parent = path.dirname(dir);
        if (parent === dir) break;
        dir = parent;
    }
    return null;
}

const patternsDir = findPatternsDir(process.cwd());
if (!patternsDir) {
    console.error('找不到 patterns/index.json，請在 slot-gen 目錄下執行');
    process.exit(1);
}

const idx = JSON.parse(fs.readFileSync(path.join(patternsDir, 'index.json'), 'utf8'));
let problems = 0;

console.log(`index.json OK — patterns=${idx.patterns.length} version=${idx.version}`);

// 2. dup id
const ids = idx.patterns.map((p) => p.id);
const dup = ids.filter((x, i) => ids.indexOf(x) !== i);
if (dup.length) {
    console.error('重複 id:', dup);
    problems++;
} else {
    console.log('duplicate ids: none');
}

// 3 + 4. 每個條目三件套與 id 一致
for (const p of idx.patterns) {
    const dir = path.join(patternsDir, p.path);
    const files = {
        meta: path.join(dir, 'metadata.json'),
        readme: path.join(dir, 'README.md'),
        impl: path.join(dir, 'implementation.ts'),
    };
    const missing = Object.entries(files)
        .filter(([, f]) => !fs.existsSync(f))
        .map(([k]) => k);
    if (missing.length) {
        console.error(`[${p.id}] 缺檔:`, missing.join(', '));
        problems++;
        continue;
    }
    let metaId = '';
    try {
        metaId = JSON.parse(fs.readFileSync(files.meta, 'utf8')).id;
    } catch (e) {
        console.error(`[${p.id}] metadata.json 解析失敗: ${e.message}`);
        problems++;
        continue;
    }
    if (metaId !== p.id) {
        console.error(`[${p.id}] metadata.id (${metaId}) 與 index 不一致`);
        problems++;
    }
}

// 5. 匹配模擬
// 以 tags(+5) / specKeywords(+8) 對一段查詢文字評分，回傳排序後的結果
function scorePatterns(searchText) {
    const scored = [];
    for (const e of idx.patterns) {
        let s = 0;
        for (const t of e.tags || []) {
            if (searchText.includes(t.toLowerCase())) s += 5;
        }
        try {
            const m = JSON.parse(fs.readFileSync(path.join(patternsDir, e.path, 'metadata.json'), 'utf8'));
            for (const k of m.specKeywords || []) {
                if (searchText.includes(k.toLowerCase())) s += 8;
            }
        } catch (err) {
            /* ignore */
        }
        if (s > 0) scored.push({ id: e.id, score: s });
    }
    scored.sort((a, b) => b.score - a.score);
    return scored;
}

const matchArgIdx = process.argv.indexOf('--match');
if (matchArgIdx !== -1 && process.argv[matchArgIdx + 1]) {
    const searchText = process.argv[matchArgIdx + 1].toLowerCase();
    const scored = scorePatterns(searchText);
    const best = scored[0];
    console.log(`\n[match] "${searchText}"\n  → best: ${best ? best.id : null} (score ${best ? best.score : 0})`);
    if (scored[1]) {
        console.log(`    runner-up: ${scored[1].id} (score ${scored[1].score})`);
    }
}

// --regression：確認每個查詢命中預期的 pattern，且新 pattern 沒搶走既有的位置
if (process.argv.includes('--regression')) {
    const casesPath = path.join(__dirname, 'regression-cases.json');
    if (!fs.existsSync(casesPath)) {
        console.error(`\n找不到 ${casesPath}`);
        process.exit(1);
    }
    const cases = JSON.parse(fs.readFileSync(casesPath, 'utf8')).cases || [];
    console.log(`\n[regression] ${cases.length} 筆查詢`);

    let failed = 0;
    let narrow = 0;
    const covered = new Set();

    for (const c of cases) {
        const scored = scorePatterns(c.query.toLowerCase());
        const best = scored[0];
        const runnerUp = scored[1];
        covered.add(c.expect);

        if (!best || best.id !== c.expect) {
            console.error(
                `  ✗ "${c.query}"\n      預期 ${c.expect}，實際 ${best ? `${best.id} (${best.score})` : 'null (0)'}`
            );
            failed++;
            continue;
        }
        // 領先幅度過小 = 隨時可能被下一個 pattern 搶走
        const gap = runnerUp ? best.score - runnerUp.score : best.score;
        if (gap <= 5) {
            console.warn(
                `  ⚠ "${c.query}"\n      ${best.id} (${best.score}) 僅領先 ${runnerUp.id} (${runnerUp.score}) ${gap} 分`
            );
            narrow++;
        }
    }

    // 沒有任何查詢守著的 pattern = 下次提取時無法偵測它被搶走
    const uncovered = idx.patterns.map((p) => p.id).filter((id) => !covered.has(id));
    if (uncovered.length) {
        console.warn(`\n  ⚠ 未納入回歸清單的 pattern（建議補上代表查詢）:\n      ${uncovered.join('\n      ')}`);
    }

    if (failed) {
        console.error(`\n[regression] ✗ ${failed} 筆未命中預期`);
        problems += failed;
    } else {
        console.log(`[regression] ✓ 全數命中預期${narrow ? `（${narrow} 筆領先幅度偏小，見上）` : ''}`);
    }
}

if (problems) {
    console.error(`\n✗ 發現 ${problems} 個問題`);
    process.exit(1);
}
console.log('\n✓ 全部通過');

