#!/usr/bin/env node
/**
 * validate_patterns.cjs
 *
 * 驗證 tools/slot-gen/patterns 的完整性，並（可選）用一段 spec 文字模擬
 * feature-composer 的關鍵詞匹配，確認新 pattern 會被命中。
 *
 * 用法（在 tools/slot-gen 目錄下執行；副檔名為 .cjs 因為 slot-gen 是 ESM 套件）：
 *   node .claude/skills/extract-uk-slot-pattern/scripts/validate_patterns.cjs
 *   node .claude/skills/extract-uk-slot-pattern/scripts/validate_patterns.cjs --match "乘倍輪盤 收集升級 multiplier"
 *
 * 檢查項目：
 *   1. index.json 可解析
 *   2. pattern id 無重複
 *   3. 每個 index 條目對應目錄的 metadata.json / README.md / implementation.ts 都存在
 *   4. metadata.json 可解析且 id 與 index 條目一致
 *   5. （--match）用 tags + specKeywords 算出最高分 pattern
 */

const fs = require('fs');
const path = require('path');

// 從目前工作目錄往上找 patterns/index.json（支援在 slot-gen 根或子目錄執行）
function findPatternsDir(start) {
    let dir = start;
    for (let i = 0; i < 6; i++) {
        const candidate = path.join(dir, 'patterns', 'index.json');
        if (fs.existsSync(candidate)) return path.join(dir, 'patterns');
        const parent = path.dirname(dir);
        if (parent === dir) break;
        dir = parent;
    }
    return null;
}

const patternsDir = findPatternsDir(process.cwd());
if (!patternsDir) {
    console.error('找不到 patterns/index.json，請在 tools/slot-gen 目錄下執行');
    process.exit(1);
}

const idx = JSON.parse(fs.readFileSync(path.join(patternsDir, 'index.json'), 'utf8'));
let problems = 0;

console.log(`index.json OK — patterns=${idx.patterns.length} version=${idx.version}`);

// 2. dup id
const ids = idx.patterns.map((p) => p.id);
const dup = ids.filter((x, i) => ids.indexOf(x) !== i);
if (dup.length) {
    console.error('重複 id:', dup);
    problems++;
} else {
    console.log('duplicate ids: none');
}

// 3 + 4. 每個條目三件套與 id 一致
for (const p of idx.patterns) {
    const dir = path.join(patternsDir, p.path);
    const files = {
        meta: path.join(dir, 'metadata.json'),
        readme: path.join(dir, 'README.md'),
        impl: path.join(dir, 'implementation.ts'),
    };
    const missing = Object.entries(files)
        .filter(([, f]) => !fs.existsSync(f))
        .map(([k]) => k);
    if (missing.length) {
        console.error(`[${p.id}] 缺檔:`, missing.join(', '));
        problems++;
        continue;
    }
    let metaId = '';
    try {
        metaId = JSON.parse(fs.readFileSync(files.meta, 'utf8')).id;
    } catch (e) {
        console.error(`[${p.id}] metadata.json 解析失敗: ${e.message}`);
        problems++;
        continue;
    }
    if (metaId !== p.id) {
        console.error(`[${p.id}] metadata.id (${metaId}) 與 index 不一致`);
        problems++;
    }
}

// 5. 匹配模擬
const matchArgIdx = process.argv.indexOf('--match');
if (matchArgIdx !== -1 && process.argv[matchArgIdx + 1]) {
    const searchText = process.argv[matchArgIdx + 1].toLowerCase();
    let best = null;
    let bestScore = 0;
    for (const e of idx.patterns) {
        let s = 0;
        for (const t of e.tags || []) {
            if (searchText.includes(t.toLowerCase())) s += 5;
        }
        try {
            const m = JSON.parse(fs.readFileSync(path.join(patternsDir, e.path, 'metadata.json'), 'utf8'));
            for (const k of m.specKeywords || []) {
                if (searchText.includes(k.toLowerCase())) s += 8;
            }
        } catch (e) {
            /* ignore */
        }
        if (s > bestScore) {
            bestScore = s;
            best = e.id;
        }
    }
    console.log(`\n[match] "${searchText}"\n  → best: ${best} (score ${bestScore})`);
}

if (problems) {
    console.error(`\n✗ 發現 ${problems} 個問題`);
    process.exit(1);
}
console.log('\n✓ 全部通過');
